head.script:
scwin.screenId = "jldstf07450";

///////// 1. 변수 및 선언 영역 /////////



///////// 2. 초기화 영역 /////////

/**
 * @method
 * @name scwin.init_loadList
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_loadList = async function () {
    // 초기 목록 — as-is 는 진입 자체가 조회였다(근거: reuse_tx). 진입점 합성이 이 단계를 잇는다.
    await scwin.tx_fn_openStkcertIsuStatDtlWin();
};

// 화면 전환 파라미터 수신 — 엔진 표준(§106). 진입 파라미터 전체를 컨텍스트 dataMap 에 담는다. onpageload 합성 단계.
/**
 * @method
 * @name scwin.init_recvParam
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        await scwin.init_loadList();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldstf07450.onpageload' });
    }
};


///////// 3. 컴포넌트 이벤트 영역 /////////

/**
 * @event
 * @name scwin.btn_print_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.btn_print_onclick = function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin btn_print_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        fn_print()
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf07450.btn_print_onclick' }); }
};

/**
 * @event
 * @name scwin.grd_stkcertIsu_oncellclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param rowIndex columnIndex columnId
 * @returns
 * @hidden N
*/
scwin.grd_stkcertIsu_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try {
        const dl = $c.util.getComponent('dlt_stkcertIsu');
        if (!dl) { console.error('[sdd] 행 동작 대상 목록 없음: dlt_stkcertIsu'); return; }
        const r = dl.getRowJSON ? dl.getRowJSON(rowIndex) : null;
        if (!r) { return; }
        if (typeof scwin.openStkcertIsuStatDtlWin === 'function') { await scwin.openStkcertIsuStatDtlWin(r["bzProcsNo"], r["stkcertIsuSeq"], r["listDdOri"]); } else { console.error('[sdd] 행 동작 미정의: scwin.openStkcertIsuStatDtlWin (열 ?)'); await $c.win.alert('이 행 동작을 아직 정하지 못했습니다(전환 미완) — scwin.openStkcertIsuStatDtlWin'); } return;
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'grd_stkcertIsu.oncellclick' });
    }
};


///////// 4. 서브미션 콜백 영역 /////////

/**
 * @method
 * @name scwin.tx_fn_openStkcertIsuStatDtlWin
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_fn_openStkcertIsuStatDtlWin = async function () {
    const sbmOptions = {
        id: "tx_fn_openStkcertIsuStatDtlWin",
        method: "post",
        action: "/konex/ListPrelmInvstgKonex.do",
        ref: "dma_openStkcertIsuStatDtlWinReq",
        target: "dlt_stkcertIsu=body.content",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { context: "jldstf07450.tx_fn_openStkcertIsuStatDtlWin" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};


///////// 5. 일반/업무 함수 영역 /////////

/**
 * @method
 * @name scwin.openStkcertIsuStatDtlWin
 * @author Inswave
 * @date 2026. 09. 29
 * @param bzprocsno stkcertIsuSeq listDd
 * @returns
 * @hidden N
*/
scwin.openStkcertIsuStatDtlWin = async function (bzprocsno, stkcertIsuSeq, listDd) {
    /* sdd-asis-lifecycle:begin fn_openStkcertIsuStatDtlWin — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const form = (document.moveForm || { elements: [] });
    $c.util.getComponent('dma_openStkcertIsuStatDtlWinReq').set('stkcertIsuSeq', stkcertIsuSeq);
    $c.util.getComponent('dma_openStkcertIsuStatDtlWinReq').set('bzProcsNoSearch', bzprocsno);
    $c.util.getComponent('dma_openStkcertIsuStatDtlWinReq').set('listDd', listDd);
    $c.util.getComponent('dma_openStkcertIsuStatDtlWinReq').set('nowPage', '61');
    await scwin.tx_fn_openStkcertIsuStatDtlWin();
    /* sdd-asis-lifecycle:end */
};
